<script setup lang="ts">
import {getApiMode} from '@/api/mode'
import {nextTick,onMounted,ref,watch} from 'vue'
import {RouterLink,useRoute} from 'vue-router'
import {usePageSeo} from '@/composables/usePageSeo'
import {useMilestones} from '@/composables/useMilestones'
import {useAuthStore} from '@/stores/auth'
import {consumeMilestonePayload} from '@/seo/payload'
import MilestoneBody from '@/components/MilestoneBody.vue'
import MilestoneEditor from '@/components/MilestoneEditor.vue'
const route=useRoute(),auth=useAuthStore(),feed=useMilestones(consumeMilestonePayload()),{scope,filter,selected}=feed,mounted=ref(false),detailPanel=ref<HTMLElement|null>(null)
const {value:list,loading:listLoading,error:listError,p:page}=feed.list,{value:detail,loading:detailLoading,error:detailError}=feed.detail
const labels={pending:'待审核',approved:'已通过',rejected:'已拒绝',unknown:'状态未知'}
function openQuery(){const id=route.query.submission;if(auth.accessToken&&typeof id==='string'&&/^\d{1,32}$/.test(id))feed.openOwned(id)}
watch(selected,async id=>{if(id&&mounted.value){await nextTick();detailPanel.value?.scrollIntoView?.({behavior:'smooth',block:'start'})}})
watch([()=>route.query.submission,()=>!!auth.accessToken,()=>auth.account?.oId],openQuery)
onMounted(()=>{mounted.value=true;openQuery()})
usePageSeo(()=>({title:scope.value==='owned'?'本人大事记投稿':'大事记',path:'/milestones',description:'摸鱼派社区大事记',robots:scope.value==='owned'?'noindex':undefined}))
</script>
<template><div class="milestones-page"><section class="card"><h1>大事记</h1><nav aria-label="大事记范围"><button type="button" :aria-pressed="scope==='public'" @click="scope='public'">公开时间线</button><button v-if="mounted&&getApiMode()==='v3'&&auth.accessToken" type="button" :aria-pressed="scope==='owned'" @click="feed.openOwned()">本人投稿</button><RouterLink v-else-if="mounted&&getApiMode()==='v3'" to="/login?redirect=/milestones">登录投稿</RouterLink></nav><p v-if="getApiMode()==='v1'">旧接口仅提供公开时间线；投稿与本人审核记录暂不支持。列表按当前公开快照分页。</p><p>{{ scope==='owned'?'当前账号提交的记录，包含待审和拒绝状态。':'只展示已审核通过的大事记，按事件日期倒序。' }}</p><label v-if="scope==='owned'">审核状态<select v-model="filter"><option value="all">全部</option><option value="pending">待审核</option><option value="approved">已通过</option><option value="rejected">已拒绝</option></select></label><button type="button" :disabled="listLoading" @click="feed.loadList()">刷新列表</button><p v-if="listLoading" role="status">正在读取大事记…</p><p v-if="listError" role="alert">{{ listError }} <button type="button" @click="feed.loadList()">重试列表</button></p><template v-if="list"><p>共{{ list.total }}条记录</p><p v-if="!list.list.length">本页没有大事记。</p><ol><li v-for="item in list.list" :key="item.id"><button type="button" @click="selected=item.id">{{ item.title }}</button><time>{{ item.date }}{{ item.endDate?' 至 '+item.endDate:'' }}</time><span v-if="item.status">{{ labels[item.status] }}</span></li></ol><nav aria-label="大事记分页"><button type="button" :disabled="listLoading||list.p<=1" @click="feed.loadList(list.p-1)">上一页</button><span>第{{ list.p }}页 / {{ list.pageCount }}页</span><button type="button" :disabled="listLoading||list.p>=Math.min(list.pageCount,42949672)" @click="feed.loadList(list.p+1)">下一页</button></nav></template><button v-if="!listLoading&&page>1&&(!list||!list.list.length)" type="button" @click="feed.loadList(1)">返回第一页</button></section>
<section v-if="selected" ref="detailPanel" class="card detail-panel"><button type="button" @click="selected=''">关闭详情</button><button type="button" :disabled="detailLoading" @click="feed.loadDetail()">刷新详情</button><p v-if="detailLoading" role="status">正在读取详情…</p><p v-if="detailError" role="alert">{{ detailError }} <button type="button" @click="feed.loadDetail()">重试详情</button></p><article v-if="detail"><h2>{{ detail.title }}</h2><p>{{ detail.date }}{{ detail.endDate?' 至 '+detail.endDate:'' }}</p><p v-if="detail.status">当前状态：{{ labels[detail.status] }}</p><MilestoneBody :item="detail" :owned="scope==='owned'"/><figure v-if="detail.media.url"><img v-if="detail.media.type==='image'" :src="detail.media.url" alt="" loading="lazy" referrerpolicy="no-referrer"/><video v-else-if="detail.media.type==='video'" :src="detail.media.url" controls preload="none"/><figcaption>{{ detail.media.caption }}</figcaption></figure><a v-if="detail.link" :href="detail.link" target="_blank" rel="noopener noreferrer">相关链接</a></article></section>
<section v-if="mounted&&getApiMode()==='v3'&&auth.accessToken" class="card"><MilestoneEditor/></section></div></template>
<style scoped lang="scss">.milestones-page{display:flex;flex-direction:column;gap:16px;max-width:900px;margin:0 auto;padding:16px}.detail-panel{scroll-margin-top:80px}.card{padding:18px;border:1px solid var(--fp-border);border-radius:12px;background:var(--fp-card);min-width:0}h1,h2{margin:0 0 12px;font-size:20px}nav,li{display:flex;flex-wrap:wrap;align-items:center;gap:12px;margin:12px 0}ol{list-style:none;padding:0}li{padding:12px 0;border-bottom:1px solid var(--fp-border)}time,p,li{overflow-wrap:anywhere}button,select{font:inherit;padding:7px;margin:3px;border:1px solid var(--fp-border);border-radius:5px;background:var(--fp-bg);color:var(--fp-text)}[role=alert]{color:#bd503c}img,video{max-width:100%;height:auto}figure{margin:16px 0}a{color:var(--fp-link)}</style>
